  "version": 1,
  "steps": [
    {
      "id": "a001_0e39a",
      "kind": "effect",
      "op": "read",
      "resource": "/synthetic/phase10/0e39a860b4/kind",
      "out": "kind_0e39a"
    },
    {
      "id": "a004_0e39a",
      "kind": "if",
      "eq": [
        {
          "var": "kind_0e39a"
        },
        "temporary"
      ],
      "then": [
        {
          "id": "a002_0e39a",
          "kind": "let",
          "name": "target_0e39a",
          "value": "/synthetic/phase10/0e39a860b4/temporary"
        }
      ],
      "else": [
        {
          "id": "a003_0e39a",
          "kind": "let",
          "name": "target_0e39a",
          "value": "/synthetic/phase10/0e39a860b4/retained"
        }
      ]
    },
    {
      "id": "a006_0e39a",
      "kind": "repeat",
      "count": 2,
      "body": [
        {
          "id": "a005_0e39a",
          "kind": "effect",
          "op": "delete",
          "resource": {
            "var": "target_0e39a"
          }
        }
      ]
    },
    {
      "id": "a007_0e39a",
      "kind": "effect",
      "op": "emit",
      "resource": "/synthetic/phase10/0e39a860b4/external",
      "value": "copper:307"
    },
    {
      "id": "a008_0e39a",
      "kind": "effect",
      "op": "write",
      "resource": "/synthetic/phase10/0e39a860b4/out",
      "value": "copper:307"
    },
    {
      "id": "a009_0e39a",
      "kind": "effect",
      "op": "read",
      "resource": "/synthetic/phase10/0e39a860b4/out"
    }
  ],
  "functions": {
    "unused_0e39a": [
      {
        "id": "a010_0e39a",
        "kind": "effect",
        "op": "write",
        "resource": "/synthetic/phase10/0e39a860b4/private",
        "value": "cold"
      }
    ]
  }
}
